// Combat Mech - actuation and endurance simulation (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var lift=[120,1500,20000], end_=[2,24,720];
console.log("Combat Mech - work capacity by generation");
console.log("==================================================");
for(var m=0;m<3;m++){
  var work=lift[m]*end_[m]; // kg-hours
  console.log("Mark "+(m+1)+": lifts "+lift[m]+" kg for "+end_[m]+" h = "+work.toLocaleString()+" kg-hours per charge");
}
console.log("Human-safety interlock: force limited near people on every generation.");

